1	package strategy
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"log/slog"
9		"os"
10		"os/exec"
11		"strings"
12		"sync"
13		"time"
14	
15		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
16		"github.com/entireio/cli/cmd/entire/cli/checkpoint/remote"
17		"github.com/entireio/cli/cmd/entire/cli/logging"
18		"github.com/entireio/cli/cmd/entire/cli/settings"
19	
20		"github.com/go-git/go-git/v6"
21		"github.com/go-git/go-git/v6/plumbing"
22		"github.com/go-git/go-git/v6/plumbing/object"
23	)
24	
25	// pushBranchIfNeeded pushes a branch to the given target if it has unpushed changes.
26	// The target can be a remote name (e.g., "origin") or a URL for direct push.
27	// When pushing to a URL, the "has unpushed" optimization is skipped since there are
28	// no remote tracking refs — git itself handles the no-op case.
29	// Does not check any settings — callers are responsible for gating.
30	func pushBranchIfNeeded(ctx context.Context, target, branchName string) error {
31		repo, err := OpenRepository(ctx)
32		if err != nil {
33			return nil //nolint:nilerr // Hook must be silent on failure
34		}
35	
36		// Check if branch exists locally
37		branchRef := plumbing.NewBranchReferenceName(branchName)
38		localRef, err := repo.Reference(branchRef, true)
39		if err != nil {
40			// No branch, nothing to push
41			return nil //nolint:nilerr // Expected when no sessions exist yet
42		}
43	
44		// Only check remote tracking refs when target is a remote name (not a URL).
45		// URLs don't have tracking refs, so we always attempt the push and let git handle it.
46		if !remote.IsURL(target) && !hasUnpushedSessionsCommon(repo, target, localRef.Hash(), branchName) {
47			return nil
48		}
49	
50		return doPushBranch(ctx, target, branchName)
51	}
52	
53	// hasUnpushedSessionsCommon checks if the local branch differs from the remote.
54	// Returns true if there's any difference that needs syncing (local ahead, remote ahead, or diverged).
55	func hasUnpushedSessionsCommon(repo *git.Repository, remoteName string, localHash plumbing.Hash, branchName string) bool {
56		// Check for remote tracking ref: refs/remotes/<remoteName>/<branch>
57		remoteRefName := plumbing.NewRemoteReferenceName(remoteName, branchName)
58		remoteRef, err := repo.Reference(remoteRefName, true)
59		if err != nil {
60			// Remote branch doesn't exist yet - we have content to push
61			return true
62		}
63	
64		// If local and remote point to same commit, nothing to sync
65		// This is the only case where we skip - any difference needs handling
66		return localHash != remoteRef.Hash()
67	}
68	
69	func displayPushTarget(target string) string {
70		if remote.IsURL(target) {
71			return "checkpoint remote"
72		}
73		return target
74	}
75	
76	// doPushBranch pushes the given branch to the target with fetch+merge recovery.
77	// The target can be a remote name or a URL.
78	func doPushBranch(ctx context.Context, target, branchName string) error {
79		displayTarget := displayPushTarget(target)
80	
81		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
82		stop := startProgressDots(os.Stderr)
83	
84		// Try pushing first
85		result, err := tryPushSessionsCommon(ctx, target, branchName)
86		if err == nil {
87			finishPush(ctx, stop, result, target)
88			return nil
89		}
90		stop("")
91	
92		// Protected refs cannot be fixed by syncing and retrying.
93		var protectedErr *protectedRefError
94		if errors.As(err, &protectedErr) {
95			printProtectedRefBlock(os.Stderr, branchName, target)
96			return nil
97		}
98	
99		// Push failed - likely non-fast-forward. Try to fetch and rebase.
100		fmt.Fprintf(os.Stderr, "[entire] Syncing %s with remote...", branchName)
101		stop = startProgressDots(os.Stderr)
102	
103		if err := fetchAndRebaseSessionsCommon(ctx, target, branchName); err != nil {
104			stop("")
105			fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync %s: %v\n", branchName, err)
106			printCheckpointRemoteHint(target)
107			return nil // Don't fail the main push
108		}
109		stop(" done")
110	
111		// Try pushing again after rebase
112		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
113		stop = startProgressDots(os.Stderr)
114	
115		if result, err := tryPushSessionsCommon(ctx, target, branchName); err != nil {
116			stop("")
117			fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push %s after sync: %v\n", branchName, err)
118			printCheckpointRemoteHint(target)
119		} else {
120			finishPush(ctx, stop, result, target)
121		}
122	
123		return nil
124	}
125	
126	// printCheckpointRemoteHint prints a hint when a push to a checkpoint URL fails.
127	// Only prints when the target is a URL (not the user's default remote).
128	func printCheckpointRemoteHint(target string) {
129		if !remote.IsURL(target) {
130			return
131		}
132		fmt.Fprintln(os.Stderr, "[entire] A checkpoint remote is configured in Entire settings (.entire/settings.json or .entire/settings.local.json) but could not be reached.")
133		fmt.Fprintln(os.Stderr, "[entire] Checkpoints are saved locally but not synced. Ensure you have access to the checkpoint remote.")
134	}
135	
136	// settingsHintOnce ensures the settings commit hint prints at most once per process.
137	var settingsHintOnce sync.Once
138	
139	// checkpointsV2MigrationHintOnce ensures the checkpoints v2 migration hint prints at most once per process.
140	var checkpointsV2MigrationHintOnce sync.Once
141	
142	// printSettingsCommitHint prints a hint after a successful checkpoint remote push
143	// when the committed .entire/settings.json does not contain a checkpoint_remote config.
144	// entire.io discovers the external checkpoint repo by reading the committed project
145	// settings, so the checkpoint_remote must be present in HEAD:.entire/settings.json
146	// (not just in settings.local.json or uncommitted local changes).
147	// Uses sync.Once to avoid duplicates when multiple branches/refs are pushed in a
148	// single pre-push invocation.
149	func printSettingsCommitHint(ctx context.Context, target string) {
150		if !remote.IsURL(target) {
151			return
152		}
153		settingsHintOnce.Do(func() {
154			if isCheckpointRemoteCommitted(ctx) {
155				return
156			}
157			fmt.Fprintln(os.Stderr, "[entire] Note: Checkpoints were pushed to a separate checkpoint remote, but .entire/settings.json does not contain checkpoint_remote in the latest commit. entire.io will not be able to discover these checkpoints until checkpoint_remote is committed and pushed in .entire/settings.json.")
158		})
159	}
160	
161	// printCheckpointsV2MigrationHint prints a hint when the committed project
162	// settings enable checkpoints_version: 2 AND there are v1 checkpoints that have
163	// not yet been mirrored into v2. Suppressed when v2 already has every v1
164	// checkpoint (nothing to migrate) so the hint does not become noise once the
165	// migration is done.
166	func printCheckpointsV2MigrationHint(ctx context.Context) {
167		checkpointsV2MigrationHintOnce.Do(func() {
168			if !isCheckpointsVersion2Committed(ctx) {
169				return
170			}
171			if !hasUnmigratedV1Checkpoints(ctx) {
172				return
173			}
174			fmt.Fprintln(os.Stderr, "[entire] Note: .entire/settings.json sets checkpoints_version: 2. Run 'entire migrate --checkpoints v2' to migrate existing checkpoints to v2.")
175			fmt.Fprintln(os.Stderr, "[entire] Use 'entire migrate --checkpoints v2 --force' to rewrite all checkpoints in v2.")
176		})
177	}
178	
179	// hasUnmigratedV1Checkpoints reports whether any v1 checkpoint has no matching
180	// entry in v2. Any failure opening the repo or listing either store is treated
181	// as "no migration needed" so we stay silent instead of printing a speculative
182	// hint — the hint is advisory and should never be the reason a push gets noisy.
183	func hasUnmigratedV1Checkpoints(ctx context.Context) bool {
184		repo, err := OpenRepository(ctx)
185		if err != nil {
186			return false
187		}
188		v1Store := checkpoint.NewGitStore(repo)
189		v1List, err := v1Store.ListCommitted(ctx)
190		if err != nil || len(v1List) == 0 {
191			return false
192		}
193		v2List, err := checkpoint.NewV2GitStore(repo, "").ListCommitted(ctx)
194		if err != nil {
195			return false
196		}
197		v2Set := make(map[string]struct{}, len(v2List))
198		for _, info := range v2List {
199			v2Set[info.CheckpointID.String()] = struct{}{}
200		}
201		for _, info := range v1List {
202			if _, ok := v2Set[info.CheckpointID.String()]; !ok {
203				summary, readErr := v1Store.ReadCommitted(ctx, info.CheckpointID)
204				if readErr != nil || summary == nil {
205					continue
206				}
207				return true
208			}
209		}
210		return false
211	}
212	
213	// isCheckpointRemoteCommitted returns true if the committed .entire/settings.json
214	// at HEAD contains a valid checkpoint_remote configuration. This is the true
215	// discoverability check: entire.io reads from committed project settings, not from
216	// local overrides or uncommitted changes.
217	func isCheckpointRemoteCommitted(ctx context.Context) bool {
218		cmd := exec.CommandContext(ctx, "git", "show", "HEAD:.entire/settings.json")
219		output, err := cmd.Output()
220		if err != nil {
221			return false // file doesn't exist at HEAD
222		}
223		// Parse the committed content and check for checkpoint_remote
224		committed, err := settings.LoadFromBytes(output)
225		if err != nil {
226			return false
227		}
228		return committed.GetCheckpointRemote() != nil
229	}
230	
231	// isCheckpointsVersion2Committed returns true if the committed .entire/settings.json
232	// at HEAD sets checkpoints_version to 2.
233	func isCheckpointsVersion2Committed(ctx context.Context) bool {
234		cmd := exec.CommandContext(ctx, "git", "show", "HEAD:.entire/settings.json")
235		output, err := cmd.Output()
236		if err != nil {
237			return false
238		}
239		committed, err := settings.LoadFromBytes(output)
240		if err != nil {
241			return false
242		}
243		return committed.CheckpointsVersion() == 2
244	}
245	
246	// pushResult describes what happened during a push attempt.
247	type pushResult struct {
248		// upToDate is true when the remote already had all commits (nothing transferred).
249		upToDate bool
250	}
251	
252	// parsePushResult checks git push --porcelain output for ref status flags.
253	// In porcelain mode, each ref gets a tab-delimited status line:
254	//
255	//	<flag>\t<from>:<to>\t<summary>
256	//
257	// where flag '=' means the ref was already up-to-date. This is locale-independent,
258	// unlike the human-readable "Everything up-to-date" message.
259	func parsePushResult(output string) pushResult {
260		for _, line := range strings.Split(output, "\n") {
261			if strings.HasPrefix(line, "=\t") {
262				return pushResult{upToDate: true}
263			}
264		}
265		return pushResult{upToDate: false}
266	}
267	
268	// finishPush stops the progress dots and prints "already up-to-date" or "done"
269	// depending on the push result. Only prints the settings commit hint when new
270	// content was actually pushed.
271	func finishPush(ctx context.Context, stop func(string), result pushResult, target string) {
272		if result.upToDate {
273			stop(" already up-to-date")
274		} else {
275			stop(" done")
276			printSettingsCommitHint(ctx, target)
277		}
278		printCheckpointsV2MigrationHint(ctx)
279	}
280	
281	// tryPushSessionsCommon attempts to push the sessions branch.
282	func tryPushSessionsCommon(ctx context.Context, remoteName, branchName string) (pushResult, error) {
283		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
284		defer cancel()
285	
286		result, err := remote.Push(ctx, remoteName, branchName)
287		outputStr := result.Output
288		if err != nil {
289			return pushResult{}, classifyPushFailure(ctx, outputStr, err)
290		}
291	
292		return parsePushResult(outputStr), nil
293	}
294	
295	// protectedRefError means the remote is blocking writes to the ref itself.
296	type protectedRefError struct {
297		output string
298	}
299	
300	func (e *protectedRefError) Error() string {
301		return "remote rejected push to protected ref"
302	}
303	
304	// isProtectedRefRejection detects GitHub ruleset and branch-protection failures.
305	func isProtectedRefRejection(output string) bool {
306		return strings.Contains(output, "GH013") ||
307			strings.Contains(output, "Cannot update this protected ref") ||
308			strings.Contains(output, "protected branch hook declined")
309	}
310	
311	var errNonFastForward = errors.New("non-fast-forward")
312	
313	func isNonFastForwardRejection(output string) bool {
314		if strings.Contains(output, "non-fast-forward") {
315			return true
316		}
317		for _, line := range strings.Split(output, "\n") {
318			if strings.Contains(line, "[rejected]") && strings.Contains(line, "(fetch first)") {
319				return true
320			}
321		}
322		return strings.Contains(output, "Updates were rejected because the tip of your current branch is behind") ||
323			strings.Contains(output, "Updates were rejected because the remote contains work that you do not have locally")
324	}
325	
326	// classifyPushOutput maps failing push stderr to a typed error.
327	func classifyPushOutput(output string) error {
328		if isProtectedRefRejection(output) {
329			return &protectedRefError{output: output}
330		}
331		if isNonFastForwardRejection(output) {
332			return errNonFastForward
333		}
334		if strings.TrimSpace(output) == "" {
335			return errors.New("push failed")
336		}
337		return fmt.Errorf("push failed: %s", output)
338	}
339	
340	func classifyPushFailure(ctx context.Context, output string, pushErr error) error {
341		if strings.TrimSpace(output) != "" {
342			if pushErr != nil {
343				logging.Debug(ctx, "git push failed",
344					slog.String("error", pushErr.Error()),
345					slog.String("output", output),
346				)
347			}
348			return classifyPushOutput(output)
349		}
350		if pushErr != nil {
351			logging.Debug(ctx, "git push failed without output",
352				slog.String("error", pushErr.Error()),
353			)
354			return fmt.Errorf("push failed: %w", pushErr)
355		}
356		return errors.New("push failed")
357	}
358	
359	// printProtectedRefBlock explains that checkpoint syncing was blocked remotely.
360	func printProtectedRefBlock(w io.Writer, ref, target string) {
361		const banner = "[entire] ============================================================"
362		displayTarget := displayPushTarget(target)
363		fmt.Fprintln(w, banner)
364		fmt.Fprintf(w, "[entire] BLOCKED: remote rejected push to %s\n", ref)
365		fmt.Fprintln(w, "[entire] Reason:  GitHub branch protection or repository ruleset (e.g. GH013)")
366		fmt.Fprintf(w, "[entire] Target:  %s\n", displayTarget)
367		fmt.Fprintln(w, "[entire] Impact:  checkpoints are saved locally but NOT synced to this remote.")
368		fmt.Fprintln(w, "[entire] Action:  allow pushes to `entire/*` in your ruleset, or set")
369		fmt.Fprintln(w, "[entire]          `checkpoint_remote` in .entire/settings.json to a separate repo.")
370		fmt.Fprintln(w, banner)
371	}
372	
373	// fetchAndRebaseSessionsCommon fetches remote sessions and rebases local commits
374	// on top of the remote tip. Since checkpoint shards use unique paths, rebases
375	// always apply cleanly.
376	// The target can be a remote name or a URL.
377	func fetchAndRebaseSessionsCommon(ctx context.Context, target, branchName string) error {
378		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
379		defer cancel()
380	
381		fetchTarget, err := remote.ResolveFetchTarget(ctx, target)
382		if err != nil {
383			return fmt.Errorf("resolve fetch target: %w", err)
384		}
385	
386		// Determine fetch refspec. When the resolved fetch target is a URL, use a
387		// temp ref; when it's still a remote name, use the standard remote-tracking
388		// ref.
389		var fetchedRefName plumbing.ReferenceName
390		var refSpec string
391		usedTempRef := remote.IsURL(fetchTarget)
392		if usedTempRef {
393			tmpRef := "refs/entire-fetch-tmp/" + branchName
394			refSpec = fmt.Sprintf("+refs/heads/%s:%s", branchName, tmpRef)
395			fetchedRefName = plumbing.ReferenceName(tmpRef)
396		} else {
397			refSpec = fmt.Sprintf("+refs/heads/%s:refs/remotes/%s/%s", branchName, target, branchName)
398			fetchedRefName = plumbing.NewRemoteReferenceName(target, branchName)
399		}
400	
401		// Use git CLI for fetch (go-git's fetch can be tricky with auth).
402		// Use --filter=blob:none for a partial fetch that downloads only commits
403		// and trees, skipping blobs. The merge only needs the tree structure to
404		// combine entries; blobs are already local or fetched on demand.
405		if output, fetchErr := remote.Fetch(ctx, remote.FetchOptions{
406			Remote:   fetchTarget,
407			RefSpecs: []string{refSpec},
408			NoTags:   true,
409		}); fetchErr != nil {
410			return fmt.Errorf("fetch failed: %s", output)
411		}
412	
413		repo, err := OpenRepository(ctx)
414		if err != nil {
415			return fmt.Errorf("failed to open git repository: %w", err)
416		}
417	
418		// Reconcile disconnected metadata branches before rebasing.
419		// The fetch above updated the remote-tracking ref, so reconciliation
420		// can compare fresh local vs remote. If disconnected (empty-orphan bug),
421		// this cherry-picks local commits onto remote tip, updating the local ref.
422		// If reconciliation fails, abort — proceeding to rebase on disconnected
423		// branches would silently combine unrelated histories.
424		if reconcileErr := ReconcileDisconnectedMetadataBranch(ctx, repo, fetchedRefName, os.Stderr); reconcileErr != nil {
425			return fmt.Errorf("metadata reconciliation failed: %w", reconcileErr)
426		}
427	
428		// Get local branch (re-read after potential reconciliation update)
429		localRef, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
430		if err != nil {
431			return fmt.Errorf("failed to get local ref: %w", err)
432		}
433	
434		// Get fetched ref (remote-tracking or temp ref, updated by the fetch above)
435		remoteRef, err := repo.Reference(fetchedRefName, true)
436		if err != nil {
437			return fmt.Errorf("failed to get remote ref: %w", err)
438		}
439	
440		// If local is already at or behind remote, fast-forward
441		if localRef.Hash() == remoteRef.Hash() {
442			return nil
443		}
444	
445		// Find merge base
446		repoPath, err := getRepoPath(repo)
447		if err != nil {
448			return fmt.Errorf("failed to get repo path: %w", err)
449		}
450		mergeBase, err := getMergeBase(ctx, repoPath, localRef.Hash().String(), remoteRef.Hash().String())
451		if err != nil {
452			return fmt.Errorf("failed to find merge base: %w", err)
453		}
454	
455		// If local is ancestor of remote (merge base == local), fast-forward to remote
456		if mergeBase == localRef.Hash() {
457			ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
458			if err := repo.Storer.SetReference(ref); err != nil {
459				return fmt.Errorf("failed to fast-forward branch ref: %w", err)
460			}
461			if usedTempRef {
462				_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
463			}
464			return nil
465		}
466	
467		// Collect commits reachable from local but not from remote and cherry-pick
468		// them onto the remote tip. This preserves local-only commits even when the
469		// local metadata branch already contains old merge commits, while avoiding
470		// replaying shared ancestors older than the true merge-base.
471		localCommits, err := collectCommitsSince(ctx, repo, repoPath, localRef.Hash(), remoteRef.Hash())
472		if err != nil {
473			return fmt.Errorf("failed to collect local commits: %w", err)
474		}
475	
476		if len(localCommits) == 0 {
477			// No local-only commits — just point to remote
478			ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
479			if err := repo.Storer.SetReference(ref); err != nil {
480				return fmt.Errorf("failed to update branch ref: %w", err)
481			}
482			if usedTempRef {
483				_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
484			}
485			return nil
486		}
487	
488		newTip, err := cherryPickOnto(ctx, repo, remoteRef.Hash(), localCommits)
489		if err != nil {
490			return fmt.Errorf("failed to rebase local commits onto remote: %w", err)
491		}
492	
493		// Update branch ref
494		newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), newTip)
495		if err := repo.Storer.SetReference(newRef); err != nil {
496			return fmt.Errorf("failed to update branch ref: %w", err)
497		}
498	
499		// Clean up temp ref if we used one (best-effort, not critical if it fails)
500		if usedTempRef {
501			_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
502		}
503	
504		return nil
505	}
506	
507	// getMergeBase returns the merge base hash of two commits, or an error if they
508	// have no common ancestor.
509	func getMergeBase(ctx context.Context, repoPath, hashA, hashB string) (plumbing.Hash, error) {
510		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
511		defer cancel()
512	
513		cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
514		cmd.Dir = repoPath
515		output, err := cmd.Output()
516		if err != nil {
517			return plumbing.ZeroHash, fmt.Errorf("git merge-base failed: %w", err)
518		}
519	
520		return plumbing.NewHash(strings.TrimSpace(string(output))), nil
521	}
522	
523	// collectCommitsSince returns non-merge commits reachable from tip but not from
524	// exclude, ordered oldest-first in topological order.
525	func collectCommitsSince(ctx context.Context, repo *git.Repository, repoPath string, tip, exclude plumbing.Hash) ([]*object.Commit, error) {
526		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
527		defer cancel()
528	
529		// cherryPickOnto computes each commit's delta against its first parent, so
530		// replaying merge commits would incorrectly re-apply changes that arrived via
531		// non-first-parent history. Limit the replay set to non-merge commits.
532		cmd := exec.CommandContext(ctx, "git", "rev-list", "--reverse", "--topo-order", "--no-merges", exclude.String()+".."+tip.String())
533		cmd.Dir = repoPath
534		output, err := cmd.Output()
535		if err != nil {
536			return nil, fmt.Errorf("git rev-list failed: %w", err)
537		}
538	
539		lines := strings.Fields(string(output))
540		if len(lines) > MaxCommitTraversalDepth {
541			return nil, fmt.Errorf("commit chain exceeded %d commits; aborting rebase", MaxCommitTraversalDepth)
542		}
543	
544		commits := make([]*object.Commit, 0, len(lines))
545		for _, line := range lines {
546			hash := plumbing.NewHash(line)
547			commit, commitErr := repo.CommitObject(hash)
548			if commitErr != nil {
549				return nil, fmt.Errorf("failed to get commit %s: %w", hash, commitErr)
550			}
551			if len(commit.ParentHashes) > 1 {
552				continue
553			}
554			commits = append(commits, commit)
555		}
556	
557		return commits, nil
558	}
559	
560	// startProgressDots prints dots to w every second until the returned stop function
561	// is called. The stop function prints the given suffix and a newline.
562	func startProgressDots(w io.Writer) func(suffix string) {
563		done := make(chan struct{})
564		stopped := make(chan struct{})
565		go func() {
566			defer close(stopped)
567			ticker := time.NewTicker(time.Second)
568			defer ticker.Stop()
569			for {
570				select {
571				case <-done:
572					return
573				case <-ticker.C:
574					fmt.Fprint(w, ".")
575				}
576			}
577		}()
578		return func(suffix string) {
579			close(done)
580			<-stopped // Wait for goroutine to finish before writing suffix
581			fmt.Fprintln(w, suffix)
582		}
583	}
584	
585	// createMergeCommitCommon creates a merge commit with multiple parents.
586	func createMergeCommitCommon(ctx context.Context, repo *git.Repository, treeHash plumbing.Hash, parents []plumbing.Hash, message string) (plumbing.Hash, error) {
587		authorName, authorEmail := GetGitAuthorFromRepo(repo)
588		now := time.Now()
589		sig := object.Signature{
590			Name:  authorName,
591			Email: authorEmail,
592			When:  now,
593		}
594	
595		commit := &object.Commit{
596			TreeHash:     treeHash,
597			ParentHashes: parents,
598			Author:       sig,
599			Committer:    sig,
600			Message:      message,
601		}
602	
603		checkpoint.SignCommitBestEffort(ctx, commit)
604	
605		obj := repo.Storer.NewEncodedObject()
606		if err := commit.Encode(obj); err != nil {
607			return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
608		}
609	
610		hash, err := repo.Storer.SetEncodedObject(obj)
611		if err != nil {
612			return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
613		}
614	
615		return hash, nil
616	}
617

