package repro

import (
	"context"
	"os/exec"
	"syscall"
	"testing"
	"time"
)

// Repro: without process-group kill + WaitDelay, exec.CommandContext leaves
// grandchildren alive and CombinedOutput blocks on inherited pipes.
func TestRepro_DefaultExecHangs(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 200*time.Millisecond)
	defer cancel()

	cmd := exec.CommandContext(ctx, "/bin/sh", "-c", "sleep 5 & echo started; wait")
	start := time.Now()
	_, _ = cmd.CombinedOutput()
	elapsed := time.Since(start)
	t.Logf("default: elapsed=%s", elapsed)
}

// Fix: Setpgid + Cancel(killgroup) + WaitDelay.
func TestRepro_WithProcessGroupKill(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 200*time.Millisecond)
	defer cancel()

	cmd := exec.CommandContext(ctx, "/bin/sh", "-c", "sleep 5 & echo started; wait")
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	cmd.Cancel = func() error {
		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
	}
	cmd.WaitDelay = 500 * time.Millisecond

	start := time.Now()
	_, _ = cmd.CombinedOutput()
	elapsed := time.Since(start)
	t.Logf("fixed: elapsed=%s", elapsed)
	if elapsed > 2*time.Second {
		t.Errorf("expected quick return; got %s", elapsed)
	}
}

